const items = $input.all();
const now = new Date();

const alerts = {
  critical: [],  // Stok habis
  low: [],       // Di bawah minimum
  expiring: [],  // Mendekati kadaluarsa
  overstock: []  // Kelebihan stok
};

let totalSKU = 0;
let totalItems = 0;
let totalValue = 0;

for (const item of items) {
  const i = item.json;
  const stok = Number(i.stok || i.stock || 0);
  const minimum = Number(i.stok_minimum || i.min_stock || 10);
  const maximum = Number(i.stok_maksimum || i.max_stock || 1000);
  const harga = Number(i.harga_beli || i.cost_price || 0);
  const expiry = i.tanggal_kadaluarsa || i.expiry_date;

  totalSKU++;
  totalItems += stok;
  totalValue += stok * harga;

  const product = {
    kode: i.kode_barang || i.sku || '-',
    nama: i.nama_barang || i.name || '-',
    kategori: i.kategori || i.category || '-',
    stok: stok,
    satuan: i.satuan || i.unit || 'pcs',
    minimum: minimum,
    supplier: i.supplier || '-',
    harga_beli: harga,
    lokasi: i.lokasi_gudang || i.warehouse || '-'
  };

  // Critical: zero stock
  if (stok === 0) {
    alerts.critical.push(product);
  }
  // Low: below minimum threshold
  else if (stok <= minimum) {
    alerts.low.push({...product, deficit: minimum - stok});
  }
  // Overstock: above maximum
  else if (stok > maximum) {
    alerts.overstock.push({...product, excess: stok - maximum});
  }

  // Expiring: within 30 days
  if (expiry) {
    const expiryDate = new Date(expiry);
    const daysUntilExpiry = Math.floor((expiryDate.getTime() - now.getTime()) / (24 * 60 * 60 * 1000));
    if (daysUntilExpiry >= 0 && daysUntilExpiry <= 30) {
      alerts.expiring.push({...product, days_until_expiry: daysUntilExpiry, expiry_date: expiry});
    }
  }
}

const hasAlerts = alerts.critical.length + alerts.low.length + alerts.expiring.length > 0;

return [{
  json: {
    tanggal: now.toLocaleDateString('id-ID', {weekday: 'long', day: '2-digit', month: 'long', year: 'numeric'}),
    total_sku: totalSKU,
    total_items: totalItems,
    total_value: totalValue,
    critical_count: alerts.critical.length,
    low_count: alerts.low.length,
    expiring_count: alerts.expiring.length,
    overstock_count: alerts.overstock.length,
    has_alerts: hasAlerts,
    critical: alerts.critical,
    low: alerts.low,
    expiring: alerts.expiring,
    overstock: alerts.overstock
  }
}];

